from __future__ import annotations

UI_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SCEI · Investigation Console</title>
<style>
:root{--bg:#f5f7fb;--panel:#fff;--ink:#172033;--muted:#667085;--line:#e4e8ef;--brand:#176b87;--brand2:#0e4d67;--accent:#dff4f4;--good:#147a5b;--warn:#a66300;--bad:#b42318;--shadow:0 12px 30px #183b4d12}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input{font:inherit}.shell{max-width:1240px;margin:auto;padding:28px 22px 56px}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:30px}.brand{display:flex;gap:12px;align-items:center}.logo{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,var(--brand),#36a2a0);color:#fff;font-weight:800;font-size:18px;box-shadow:0 8px 18px #176b8733}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:11px;color:var(--brand);font-weight:800}.brand h1{font-size:20px;line-height:1.1;margin:2px 0}.top-status{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:#28a879;box-shadow:0 0 0 4px #28a87920}.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:18px;margin-bottom:18px}.hero-copy{padding:30px;border-radius:20px;background:linear-gradient(135deg,#113f59,#176b87 62%,#2c9690);color:#fff;box-shadow:var(--shadow)}.hero-copy h2{font-size:30px;line-height:1.12;margin:8px 0 12px;max-width:620px}.hero-copy p{color:#d9edf0;max-width:600px;margin:0}.hero-note{padding:24px;border:1px solid #cfe3e8;border-radius:20px;background:var(--accent);color:#164c5a}.hero-note strong{display:block;font-size:16px;margin-bottom:8px}.workspace{display:grid;grid-template-columns:360px 1fr;gap:18px;align-items:start}.panel,.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:var(--shadow)}.panel{padding:20px;position:sticky;top:18px}.panel h3,.card h3{margin:0 0 4px;font-size:16px}.sub{color:var(--muted);font-size:12px;margin:0 0 18px}.mode-tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:#f1f4f7;padding:4px;border-radius:10px;margin-bottom:18px}.mode-tabs button{border:0;background:transparent;color:var(--muted);padding:9px;border-radius:7px;cursor:pointer}.mode-tabs button.active{background:#fff;color:var(--brand2);font-weight:700;box-shadow:0 2px 8px #17203312}.field{margin:12px 0}.field label{display:flex;justify-content:space-between;gap:8px;font-size:12px;font-weight:700;margin-bottom:6px}.hint{font-size:11px;font-weight:400;color:var(--muted)}input{width:100%;border:1px solid #cbd3dd;border-radius:8px;padding:10px 11px;color:var(--ink);background:#fff;outline:none}input:focus{border-color:var(--brand);box-shadow:0 0 0 3px #176b8718}.primary{width:100%;border:0;border-radius:9px;padding:11px 14px;background:var(--brand);color:#fff;font-weight:750;cursor:pointer;margin-top:10px}.primary:hover{background:var(--brand2)}.secondary{border:1px solid #b9c8d2;border-radius:8px;background:#fff;color:var(--brand2);padding:8px 11px;cursor:pointer}.main{display:grid;gap:18px}.empty{padding:46px 24px;text-align:center;color:var(--muted)}.empty-icon{font-size:32px;margin-bottom:8px}.result-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding:20px 20px 0}.result-head h3{font-size:18px}.badge{border-radius:999px;padding:5px 10px;background:#edf2f6;color:var(--muted);font-size:11px;font-weight:750}.badge.good{background:#e7f6ef;color:var(--good)}.badge.warn{background:#fff4df;color:var(--warn)}.summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:18px 20px}.metric{padding:13px;border:1px solid var(--line);border-radius:11px;background:#fbfcfd}.metric b{display:block;font-size:22px;color:var(--brand2)}.metric span{color:var(--muted);font-size:11px}.section{padding:0 20px 20px}.section h4{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:12px 0 9px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f8fafc;color:var(--muted);font-weight:700}tr:last-child td{border-bottom:0}.json{margin:0;background:#101b26;color:#d4e7ed;border-radius:10px;padding:14px;max-height:360px;overflow:auto;font:11px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}.error{margin:0 20px 18px;padding:12px;border-radius:9px;background:#fff0ee;color:var(--bad);border:1px solid #f2c8c3}.hidden{display:none!important}.footer{color:var(--muted);font-size:11px;text-align:center;margin-top:24px}@media(max-width:850px){.hero,.workspace{grid-template-columns:1fr}.panel{position:static}.summary{grid-template-columns:repeat(2,1fr)}.top-status{display:none}}@media(max-width:480px){.shell{padding:18px 12px 40px}.hero-copy h2{font-size:25px}.result-head{display:block}}
</style></head><body><div class="shell">
<header class="topbar"><div class="brand"><div class="logo">S</div><div><div class="eyebrow">Evidence intelligence</div><h1>Supply Chain Investigation</h1></div></div><div class="top-status"><span class="dot"></span> Local workspace · SQLite</div></header>
<section class="hero"><div class="hero-copy"><div class="eyebrow" style="color:#a8e1df">Pharmaceutical batch contamination</div><h2>Trace what happened, where it moved, and what it affected.</h2><p>Run a tenant-scoped investigation across verified genealogy relationships, dataset contexts, quantities, and source provenance.</p></div><div class="hero-note"><strong>Evidence-first by design</strong><span>Every returned relationship is linked to its source event and projection context. Unresolved paths are surfaced as warnings.</span></div></section>
<div class="workspace"><aside class="panel"><h3>Start an investigation</h3><p class="sub">Choose a workflow and provide identifiers from your active dataset context.</p><div class="mode-tabs"><button id="batchTab" class="active" type="button">Batch lookup</button><button id="incidentTab" type="button">Incident report</button></div>
<form id="batchForm"><div class="field"><label for="org">Organization ID <span class="hint">required</span></label><input id="org" required placeholder="UUID"></div><div class="field"><label for="context">Projection context <span class="hint">recommended</span></label><input id="context" placeholder="UUID"></div><div class="field"><label for="batch">Batch identifier <span class="hint">code or label</span></label><input id="batch" required placeholder="BATCH-BD-00000001"></div><div class="field"><label for="hops">Traversal depth <span id="hopsValue" class="hint">5 hops</span></label><input id="hops" type="range" min="1" max="20" value="5"></div><button class="primary">Run batch investigation →</button></form>
<form id="incidentForm" class="hidden"><div class="field"><label for="incidentOrg">Organization ID <span class="hint">required</span></label><input id="incidentOrg" required placeholder="UUID"></div><div class="field"><label for="incidentContext">Projection context <span class="hint">recommended</span></label><input id="incidentContext" placeholder="UUID"></div><div class="field"><label for="incidentId">Incident ID <span class="hint">required</span></label><input id="incidentId" required placeholder="INC-BD-20261031-0002"></div><div class="field"><label for="incidentHops">Traversal depth <span id="incidentHopsValue" class="hint">5 hops</span></label><input id="incidentHops" type="range" min="1" max="20" value="5"></div><button class="primary">Run incident report →</button></form><button id="clear" class="secondary" style="width:100%;margin-top:10px" type="button">Clear result</button></aside>
<main class="main"><section id="empty" class="card empty"><div class="empty-icon">⌁</div><h3>Your investigation will appear here</h3><p>Start with a batch or incident. Use a projection context to prevent historical datasets from being mixed.</p></section><section id="output" class="card hidden"><div class="result-head"><div><div class="eyebrow">Investigation result</div><h3 id="resultTitle">Completed</h3></div><span id="resultBadge" class="badge good">Verified context</span></div><div class="summary"><div class="metric"><b id="mNodes">—</b><span>Nodes traversed</span></div><div class="metric"><b id="mEdges">—</b><span>Edges traversed</span></div><div class="metric"><b id="mProducts">—</b><span>Products affected</span></div><div class="metric"><b id="mWarnings">—</b><span>Warnings</span></div></div><div id="error" class="error hidden"></div><div class="section"><h4>Impact summary</h4><div id="impact"></div></div><div class="section"><h4>Evidence paths</h4><div id="paths"></div></div><div class="section"><details><summary style="cursor:pointer;color:var(--brand2);font-weight:700">Show raw response</summary><pre id="raw" class="json" style="margin-top:10px"></pre></details></div></section></main></div><div class="footer">SCEI · Tenant-scoped · Context-aware · Provenance-preserving</div></div>
<script>
const $=id=>document.getElementById(id);function setMode(mode){const i=mode==='incident';$('batchTab').classList.toggle('active',!i);$('incidentTab').classList.toggle('active',i);$('batchForm').classList.toggle('hidden',i);$('incidentForm').classList.toggle('hidden',!i)}function slider(id,out){$(id).oninput=()=>$(out).textContent=$(id).value+' hops'}slider('hops','hopsValue');slider('incidentHops','incidentHopsValue');$('batchTab').onclick=()=>setMode('batch');$('incidentTab').onclick=()=>setMode('incident');function showEmpty(){$('empty').classList.remove('hidden');$('output').classList.add('hidden')}function render(d,title){$('empty').classList.add('hidden');$('output').classList.remove('hidden');$('resultTitle').textContent=title;$('resultBadge').textContent='Verified context';$('raw').textContent=JSON.stringify(d,null,2);const i=d.contamination_impact||{},g=d.genealogy||d.downstream||{},p=g.paths||[];$('mNodes').textContent=g.visited_node_ids?.length??i.traversed_nodes??'—';$('mEdges').textContent=i.traversed_edges??p.reduce((n,x)=>n+(x.edge_ids||[]).length,0);$('mProducts').textContent=(i.confirmed_products||[]).length+(i.possible_products||[]).length;$('mWarnings').textContent=(d.completeness_warnings||g.completeness_warnings||i.unresolved_gaps||[]).length;const products=[...(i.confirmed_products||[]),...(i.possible_products||[])];$('impact').innerHTML=products.length?'<div class="table-wrap"><table><thead><tr><th>Product ID</th><th>Confidence</th><th>Shortest path</th></tr></thead><tbody>'+products.map(x=>`<tr><td>${x.product_id}</td><td><span class="badge ${x.state==='VERIFIED'?'good':'warn'}">${x.state}</span></td><td>${x.shortest_hops} hops</td></tr>`).join('')+'</tbody></table></div>':'<p class="sub">No downstream products were confirmed in this context.</p>';$('paths').innerHTML=p.length?'<div class="table-wrap"><table><thead><tr><th>Hops</th><th>Relationship</th><th>Event</th><th>Provenance</th></tr></thead><tbody>'+p.slice(0,12).map(x=>{const e=x.edge_details?.[x.edge_details.length-1]||{};return `<tr><td>${x.hop_count}</td><td>${e.edge_type||'—'}</td><td>${e.event_id||'—'}</td><td>${e.provenance?.[0]?.document_id||'—'}</td></tr>`}).join('')+'</tbody></table></div>':'<p class="sub">No paths returned.</p>'}async function call(url,o){const r=await fetch(url,o),d=await r.json();if(!r.ok)throw Error(d.detail||r.statusText);return d}function running(t){$('empty').classList.add('hidden');$('output').classList.remove('hidden');$('resultTitle').textContent=t;$('resultBadge').textContent='Running…';$('resultBadge').className='badge warn';$('impact').innerHTML='<p class="sub">Querying the projection context…</p>';$('paths').innerHTML='';$('error').classList.add('hidden')}function failed(e){$('resultBadge').textContent='Needs attention';$('resultBadge').className='badge warn';$('error').textContent=e;$('error').classList.remove('hidden')}$('batchForm').onsubmit=async e=>{e.preventDefault();running('Running batch investigation');try{const q={organization_id:$('org').value,batch_query:$('batch').value,max_hops:+$('hops').value,max_paths:500,include_possible:false};if($('context').value)q.context_id=$('context').value;render(await call('/v1/investigations/batch',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(q)}),'Batch investigation complete')}catch(x){failed(x.message)}};$('incidentForm').onsubmit=async e=>{e.preventDefault();running('Running incident report');try{const q={organization_id:$('incidentOrg').value,incident_id:$('incidentId').value,max_hops:+$('incidentHops').value,max_paths:500,include_possible:false};if($('incidentContext').value)q.context_id=$('incidentContext').value;render(await call('/v1/investigations/incident',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(q)}),'Incident investigation complete')}catch(x){failed(x.message)}};$('clear').onclick=showEmpty;
</script></body></html>'''
